values.value:
{
  "fields": [
    {
      "apiName": "freight_incoterms_hdpe",
      "label": "Trans.in offer?",
      "type": "picklist",
      "formula":"(p_Type_of_transportation == 'F.O.R (Freight on Road)' || d_Type_of_transportation == 'F.O.R (Freight on Road)' || is_Type_of_transportation == 'F.O.R (Freight on Road)' || Type_of_transportation == 'F.O.R (Freight on Road)') ? 'F.O.R (Freight on Road)' : 'Ex-works'",
      "readOnly":true,
      "options": [
      "Ex-works",
      "F.O.R (Freight on Road)"
      ]
    },
    {
      "apiName": "terms_and_conditions_folder",
      "label": "Terms & Conditions",
      "type": "folder",
      "iconColor": "red",
      "controllingField": "freight_incoterms_hdpe",
      "controllingValues": [
        "*"
      ],
      "modalConfigsByValue": {
        "default": {
          "title": "TERMS & CONDITIONS",
          "modalFields": [
            {
              "id": "tc_details",
              "label": "Terms & Condition Details",
              "expanded": true,
              "fields": [
                {
                  "apiName": "tc_packing_forwarding_charges",
                  "label": "Packing & Forwarding Charges",
                  "type": "picklist",
                  "options": ["Inclusive", "Exclusive"],
                  "defaultValue": "Inclusive",
                  "colSpan": 12
                },
                {
                  "apiName": "tc_payment_term",
                  "label": "Payment Terms",
                  "type": "text",
                  "defaultValue": "Advance",
                  "colSpan": 12
                },
                {
                  "apiName": "tc_validity",
                  "label": "Validity",
                  "type": "text",
                  "defaultValue": "valid for a time till revision in Raw Material Price",
                  "colSpan": 12
                },
                {
                  "apiName": "tc_test_certificate",
                  "label": "Third Party Test Certificate",
                  "type": "picklist",
                  "options": ["Included","Excluded"],
                  "defaultValue": "Excluded",
                  "colSpan": 12
                },
                {
                  "apiName": "tc_warranty_start",
                  "label": "Warranty from Date of commissioning in Months",
                  "type": "number",
                  "defaultValue":12,
                  "colSpan": 12
                },
				        {
                  "apiName": "tc_warranty_end",
                  "label": "Warranty from date of delivery in Months",
                  "type": "number",
                  "defaultValue":18,
                  "colSpan": 12
                },
                {
                  "apiName": "tc_freight",
                  "label": "Freight",
                  "type": "textarea",
                  "controllingField":"tc_packing_forwarding_charges",
                  "controllingValues":["hidden"],
                  "defaultValue": "",
                  "colSpan": 12
                },
                {
                  "apiName": "tc_Insurance",
                  "label": "Insurance",
                  "type": "text",
                  "colSpan": 12,
                  "defaultValue":"To be borne & arrange by you"
                },
                {
                  "apiName": "tc_destination_location",
                  "label": "Delivery Location",
                  "type": "text",
                  "colSpan": 12,
                  "defaultValue":"Kolkata"
                }
              ]
            }
          ]
        }
      }
    }
  ]
}
